//! Shum's stickers from the design: 17 sets of pixel pictures, emoji on a
//! 16-cell grid and characters on a 32-cell one. Every client draws them
//! from here. Sets of phrases are stickers only; the rest are reactions too.
//! Generated from the design's sticker page; do not edit by hand.

/// A square picture: one symbol a cell, `.` transparent, colors by symbol.
pub struct Art {
    pub size: usize,
    pub colors: &'static [u32],
    pub cells: &'static str,
}

pub struct Sticker {
    /// Its name in the protocol.
    pub id: &'static str,
    /// The emoji and the word it stands for, for search, pushes and older
    /// versions of Shum.
    pub emoji: &'static str,
    pub word: &'static str,
    pub art: Art,
}

pub struct Set {
    pub id: &'static str,
    /// Its title in Russian; clients translate it.
    pub title: &'static str,
    /// Whether its stickers are reactions too; phrases are not.
    pub reactions: bool,
    /// Its picture in a list of sets.
    pub icon: Art,
    pub stickers: &'static [Sticker],
}

